NAME = 'ACV: A Conservative Version'
BOOK = 'Amos'

CHAPTERS = {
    1: {
        1: 'Besede Amosa, bivšega ovčarja v Tekoi, ki jih je v prikazni slišal za Izraela v dneh Uzija, kralja Judovega, in v dneh Jeroboama, sina Joasa, kralja Izraelovega, dve leti pred potresom.',
        2: 'In je rekel: Gospod bo rjovel s Siona in grmel z glasom svojim iz Jeruzalema, in žalovali bodo pašniki pastirjev in vrh Karmela se bo posušil.',
        3: 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih je kriv Damask, ne odvrnem šibe njegove: ker so mlatili Gileada z železnimi mlatilnicami,',
        4: 'zato pošljem ogenj v hišo Hazaelovo, in požre gradove Ben-hadadove.',
        5: 'In potarem zapahe v Damasku in iztrebim prebivalce iz doline Avenske in njega, ki drži žezlo, iz hiše edenske; in ljudstvo iz Sirije pojde v sužnost v Kir, pravi Gospod.',
        6: 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih je kriva Gaza, ne odvrnem šibe njene: ker so peljali ljudstvo prav vse v ujetništvo, da jih izroče Edomu,',
        7: 'zato pošljem ogenj v obzidje Gaze, in požre palače njene,',
        8: 'in iztrebim prebivalca iz Asdoda in njega, ki drži žezlo, iz Askelona; in obrnem roko svojo zoper Ekron, in pogine ostanek Filistejcev, pravi Gospod Jehova.',
        9: 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih je kriv Tir, ne odvrnem šibe njegove: ker so izročili ujetnike Edomu in se niso spomnili bratovske zaveze,',
        10: 'zato pošljem Tiru ogenj v obzidje, in požre palače njegove.',
        11: 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih je kriv Edom, ne odvrnem šibe njegove: ker je preganjal z mečem brata svojega in zadušil usmiljenje v sebi, in ker je v jezi svoji neprenehoma pobijal in srd svoj vedno razvnemal,',
        12: 'zato pošljem ogenj v Teman, in požre palače v Bozri.',
        13: 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih so krivi sinovi Amonovi, ne odvrnem šibe od njih: ker so razparali noseče v Gileadu, da razširijo meje svoje,',
        14: 'zato zažgem ogenj v zidovju Rabe, in požre palače njene med bojnim vpitjem v dan bitke, v viharju ob dnevi nevihte;',
        15: 'in njih kralj pojde v ujetništvo, on in knezi njegovi skupaj, pravi Gospod.',
    },
    2: {
        1: 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih je kriv Moab, ne odvrnem šibe njegove: ker je sežgal kosti kralja edomskega do apna,',
        2: 'zato pošljem ogenj nad Moaba, in požre palače v Kerjotu; in Moab umrje v hrupu, med bojnim krikom, med bučanjem trobente;',
        3: 'in iztrebim sodnika izmed njega in vse poglavarje njegove umorim ž njim vred, pravi Gospod.',
        4: 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih je kriv Juda, ne odvrnem šibe njegove: ker so zavrgli zakon Gospodov in niso ohranili postav njegovih, njih laži pa, po katerih so živeli njih očetje, so jih zapeljale,',
        5: 'zato pošljem ogenj nad Judo, in požre palače jeruzalemske.',
        6: 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih je kriv Izrael, ne odvrnem šibe njegove: ker so prodali pravičnika za denar in potrebnega za par čevljev;',
        7: 'oni hrepene po tem, da vidijo prah zemlje na glavi ubožca in krivijo pot krotkim, in sin in oče hodita k enemu dekletu, da bi oskrunila ime svetosti moje;',
        8: 'in na zastavljenih oblačilih leže pri slehernem oltarju in v hiši Boga svojega pijo vino tistih, ki jim je bila prisojena globa.',
        9: 'In vendar sem pogubil Amorejca izpred njih, ki je bil visok kakor cedra in močan kakor hrast, vendar sem pogubil njegov sad zgoraj in korenine njegove spodaj.',
        10: 'In jaz sem vas odpeljal iz dežele egiptovske in vas vodil štirideset let v puščavi, da bi posedli deželo Amorejcev.',
        11: 'In obudil sem proroke izmed vaših sinov in nazirce iz vaših mladeničev. Ni li prav tako, o sinovi Izraelovi? govori Gospod.',
        12: 'Vi pa ste dajali vina piti nazircem in prorokom ste ukazovali: Ne prorokujte!',
        13: 'Glejte, jaz vas bom tlačil do tal kakor tlači voz, ki je poln snopja.',
        14: 'In izgine beg hitremu in močnega opusti moč njegova, in junak ne otme življenja svojega,',
        15: 'in lokostrelec ne bo mogel stati, in kdor je brzih nog, ne ubeži, in kdor jezdi konja, ne otme življenja svojega,',
        16: 'in najpogumnejši med junaki bo nag bežal tisti dan, govori Gospod.',
    },
    3: {
        1: 'Čujte to besedo, ki jo Gospod govori zoper vas, sinovi Izraelovi, zoper vso rodovino, ki sem jo peljal gori iz Egipta, ko pravi:',
        2: 'Samo vas sem spoznal izmed vseh rodovin na zemlji; zato bom kaznoval nad vami vse krivice vaše.',
        3: 'Moreta li dva skupaj hoditi, ako se ne sporazumeta?',
        4: 'Rjove li lev v gozdu, če nima ropa? Zažene li levič glas svoj iz brloga, ako ni kaj ulovil?',
        5: 'Zaplete li se mar ptica v mrežo na zemlji, če ji ni nastavljena zanka? Dvigne li se past od zemlje, če se ni nič ujelo?',
        6: 'Zabuči li trobenta v mestu, in ljudstvo se ne prestraši? Ali se pa v mestu zgodi nesreča, katere bi Gospod ne bil napravil?',
        7: 'Kajti Gospod Jehova ne stori ničesar, da bi ne razodel skrivnosti svoje služabnikom svojim, prorokom.',
        8: 'Lev je rjovel, kdo naj bi se ne bal? Gospod Jehova je govoril, kdo naj bi ne prorokoval?',
        9: 'Razglasite nad palačami v Asdodu in nad palačami po deželi Egiptovski in recite: Zberite se na samarijskih gorah in poglejte, kakšna grozna zmešnjava je v Samariji in koliko zatiranja sredi nje!',
        10: 'In ne znajo pošteno ravnati, govori Gospod, tisti, ki kopičijo, kar so s krivico in silo pridobili, v palačah svojih.',
        11: 'Zatorej pravi tako Gospod Jehova: Sovražnik bode okoli vse dežele in zvrne moč tvojo s tebe na tla, in oplenjene bodo palače tvoje.',
        12: 'Tako pravi Gospod: Kakor pastir otme levu iz žrela dve krači ali konec ušesa, tako bodo oteti sinovi Izraelovi, ki sedé v Samariji v kotu na blazini ali na damastovi počivalnici.',
        13: 'Poslušajte in izpričajte to zoper hišo Jakobovo, govori Gospod Jehova, Bog nad vojskami:',
        14: 'tisti dan, kadar bom kaznoval pregrehe Izraelove na njem, obiščem tudi oltarje v Betelu, in odbiti bodo rogovi oltarju, da popadajo na tla.',
        15: 'In podrem zimsko hišo s poletno hišo vred, in pokončane bodo hiše slonokoščene, velike hiše izginejo, govori Gospod.',
    },
    4: {
        1: 'Čujte to besedo, krave basánske, ki ste na gori Samarije, ki tlačite ubožca, tarete potrebnega in pravite svojim gospodarjem: Prinesi, da pijemo!',
        2: 'Prisegel je Gospod Jehova pri svetosti svoji: Glejte, pridejo dnevi nad vas, da vas bodo vlekli stran s trnki in ostanek vaš z vodicami.',
        3: 'In pojdete ven skozi vrzeli, vsaka naravnost predse, in boste pahnjene v Harmon, govori Gospod.',
        4: 'Le hodíte v Betel in se pregrešujte, v Gilgalu množite prestopke! In prinašajte vsako jutro klalne daritve, vsak tretji dan desetine svoje;',
        5: 'in zažigajte okvašeno v hvalno daritev ter razglašujte prostovoljne darove in jih oznanjajte! To vam je namreč všeč, o sinovi Izraelovi, govori Gospod Jehova.',
        6: 'Saj tudi jaz sem vam dal čiste zobe po vseh mestih vaših in pomanjkanje kruha po vseh krajih vaših, a vendar se niste povrnili prav do mene, govori Gospod.',
        7: 'In jaz sem vam tudi zadržal dež, ko je bilo še tri mesece do žetve; in na eno mesto sem dal dežiti, na drugo pa ne, ena njiva je bila z dežjem pomočena, njiva pa, ki nanjo ni dežilo, se je posušila;',
        8: 'in iz dveh, treh mest so se opotekali do enega mesta, da bi pili vodo, a niso se odžejali. Vendar se niste povrnili prav do mene, govori Gospod.',
        9: 'Udaril sem vas snetjo in strupeno roso, množino vaših vrtov in vinogradov in smokev in oljk so požrle kobilice. Vendar se niste povrnili prav do mene, govori Gospod.',
        10: 'Poslal sem med vas kugo po načinu egiptovskem; mladeniče vaše sem usmrtil z mečem in obenem sem dal odpeljati vaše konje in storil sem, da je smrad iz vaših šatorišč puhtel prav do vaših nosnic. Vendar se niste povrnili prav do mene, govori Gospod.',
        11: 'Razdejal sem nekatere kraje vaše, kakor je Bog razdejal Sodomo in Gomoro; in bili ste kakor glavnja, potegnjena iz ognja. Vendar se niste povrnili prav do mene, govori Gospod.',
        12: 'Zavoljo tega ti hočem tako storiti, o Izrael; in ker ti to hočem storiti, pripravi se, Izrael, da pojdeš Bogu naproti!',
        13: 'Kajti, glej, on, ki upodablja gore in ustvarja veter in oznanja človeku, kakšno je mišljenje njegovo, ki dela iz jutranje zarje temo in stopa po višavah zemeljskih: Jehova, Bog nad vojskami, je ime njegovo.',
    },
    5: {
        1: 'Čujte to besedo, žalostinko, ki jo pojem nad vami, o hiša Izraelova!',
        2: 'Padla je devica Izraelova, ne vstane več, vržena je ob tla, ni ga, ki bi jo vzdignil.',
        3: 'Kajti tako pravi Gospod Jehova: Mestu, iz katerega jih je hodilo tisoč, jih preostane sto, in njemu, iz katerega jih je hodilo sto, jih preostane deset za hišo Izraelovo.',
        4: 'Kajti tako pravi Gospod hiši Izraelovi: Iščite me, in boste živeli!',
        5: 'In ne iščite Betela in ne hodite v Gilgal in ne zahajajte v Bersebo; kajti Gilgal bo gotovo odpeljan v sužnost in Betel pride v nič.',
        6: 'Iščite Gospoda, in boste živeli! Sicer pridere kakor ogenj v hišo Jožefovo in jo požre, in ne bo v Betelu nikogar, ki bi pogasil.',
        7: 'Vi, ki prevračate pravico v pelin in teptate pravičnost,',
        8: 'iščite njega, ki je naredil gostosevce in rimščice, ki izpreminja smrtno senco v jutro in dan mrači v noč, ki kliče vode iz morja ter jih razliva po površju zemlje: Jehova je ime njegovo;',
        9: 'ki spravlja naglo potrtje nad močnega, da pokončevanje nastane v trdnjavi.',
        10: 'Oni sovražijo njega, ki pravično razsoja med vrati, in studijo njega, ki govori o brezmadežnosti.',
        11: 'Zatorej, ker teptate ubožca in od njega izterjavate davek od žita: sezidali ste hiše iz obdelanih kamenov, a ne boste prebivali v njih, zasadili ste krasne vinograde, a ne boste pili vina iz njih.',
        12: 'Vem namreč, kako obilni so prestopki vaši in kako mnogoštevilni grehi vaši – da stiskate pravičnika, jemljete podkupila in krivite pravico revežev med vrati.',
        13: 'Zato, kdor je moder, molči v tem času, ker čas je hud.',
        14: 'Iščite dobrega, ne pa hudega, da boste živeli; in tako bode z vami Gospod, Bog nad vojskami, kakor pravite.',
        15: 'Sovražite hudo in ljubite dobro, uveljavite pravico med vrati; morda se usmili Gospod, Bog nad vojskami ostanka Jožefovega.',
        16: 'Zatorej pravi tako Jehova, Bog nad vojskami, Gospod: Po vseh trgih bo plakanje; in po vseh ulicah bodo vpili: Gorje, gorje! in klicali bodo orača k žalovanju in izučene k žalovanju, naj plakajo;',
        17: 'in po vseh vinogradih bode plakanje. Kajti pojdem skozi tebe, pravi Gospod.',
        18: 'Gorje vam, ki želite dneva Gospodovega! Čemu naj vam bode dan Gospodov? Tema bode, ne pa luč.',
        19: 'Bode, kakor če kdo beži izpred leva, pa ga sreča medved; in stopi v hišo ter se nasloni na steno z roko, in ga piči kača.',
        20: 'Ne bode li dan Gospodov tema, ne pa luč? črn mrak, ne pa svetloba?',
        21: 'Sovražim, zaničujem praznike vaše in slavnostna zborovanja vaša mi niso všeč;',
        22: 'ako mi tudi darujete žgalne in jedilne dritve, mi niso prijetne, in na mirovne daritve od vaše pitane živine se ne maram ozreti.',
        23: 'Spravi izpred mene vrišč svojih pesmi, in brenkanja tvojih strun nočem poslušati.',
        24: 'A naj se privali pravica kakor voda in pravičnost kakor vedno tekoč potok!',
        25: 'Ali ste mi darovali v puščavi klalne in jedilne daritve štirideset let, o hiša Izraelova?',
        26: 'Res, nosili ste šator svojega kralja in kip svojih malikov, zvezdo boga svojega, kar ste si naredili.',
        27: 'Zato vas prepeljem v ujetništvo onostran Damaska, pravi Gospod, čigar ime Bog nad vojskami.',
    },
    6: {
        1: 'Gorje lahkoživcem na Sionu in brezskrbnežem na gori Samarije, imenitnikom prvega med narodi, h katerim hodi hiša Izraelova!',
        2: 'Pojdite tja v Kalne in poglejte, in preidite odondod v veliki Hamat, potem stopite doli v Gat Filistejcev: so li odličnejši nego ta kraljestva, ali pa je njih pokrajina večja od vaše pokrajine?',
        3: 'vi, ki želite, da bodi daleč dan nesreče, in stol silovitosti si stavite blizu,',
        4: 'ki ležite na slonokoščenih posteljah in se raztegujete po svojih počivalnicah in jeste jagnjeta od črede in teleta iz pitalnice,',
        5: 'ki pojete bedaste pesmi z glasom brenkelj, si izmišljate godala kakor David,',
        6: 'ki pijete vino iz daritvenih čaš in se mazilite z najboljšimi mazili, a se ne žalostite nad rano Jožefovo.',
        7: 'Zato pojdejo v sužnost na čelu ujetnikov, in preneha vriskanje njih, ki so se lenobno raztegovali.',
        8: 'Gospod, Jehova, je prisegel pri samem sebi, govori Gospod, Bog nad vojskami: Jaz studim ponos Jakobov in sovražim palače njegove, zato izročim sovražniku mesto in vse, kar je v njem.',
        9: 'In zgodi se, ako ostane deset mož v eni hiši, vendar umrjo.',
        10: 'In kadar koga vzdigne sorodnik njegov, ki mu bo pogrebnik, da spravi kosti iz hiše, in ogovori njega, ki je v notranjem hišnem hramu: Je li še kdo pri tebi? ta pa reče: Nikogar ni več; tedaj poreče: Mólči! ker se ne sme spominjati imena Gospodovega.',
        11: 'Kajti glej, Gospod ukaže, in udarijo veliko hišo, da bode v podrtine, in malo hišo, da bode v drobir.',
        12: 'Morejo li konji dirjati po skalovju, se li more morje orati z voli? da ste izprevrgli pravico v strup in sad pravičnosti v pelin?',
        13: 'vi, ki se veselite tega, kar ni nič, ki govorite: Si li nismo po svoji moči dobili rogov?',
        14: 'Kajti glejte, obudim zoper vas narod, o hiša Izraelova, govori Gospod, Bog nad vojskami, in vas bodo stiskali od vhoda v Hamat prav do potoka nižine Arabe.',
    },
    7: {
        1: 'To mi je pokazal Gospod Jehova: Glej, napravljal je roj kobilic, ko je jela poganjati otava; in glej, bila je otava po kraljevi košnji.',
        2: 'In zgodi se, ko so dočista požrle vso travo zemlje, da rečem: O, Gospod Jehova, odpústi, prosim! kako naj obstoji Jakob? saj je majhen.',
        3: 'Gospodu je bilo žal za to. Ne bo se zgodilo, je rekel Gospod.',
        4: 'To mi je pokazal Gospod Jehova: Glej, Gospod Jehova je klical ogenj, da po njem izvrši sodbo; in požrl je ogenj veliko brezno in je hotel požreti tudi orno zemljo.',
        5: 'Tedaj rečem: O, Gospod Jehova, odnehaj, prosim! kako naj obstoji Jakob? saj je majhen.',
        6: 'Gospodu je bilo žal za to. Tudi to se ne zgodi, je rekel Gospod Jehova.',
        7: 'To mi je pokazal: Glej, Gospod je stal na navpičnem zidu, in v roki njegovi je bila olovnica.',
        8: 'In Gospod mi reče: Kaj vidiš, Amos? In odgovorim: Olovnico. In Gospod reče: Glej, denem olovnico na ljudstvo svoje izraelsko, po sredi njegovi; ne pojdem več mimo njega, prizanašajoč mu.',
        9: 'In opustošene bodo višave Izakove in svetišča Izraelova bodo razdejana; in z mečem vstanem zoper hišo Jeroboamovo.',
        10: 'Tedaj je poslal Amazija, duhovnik v Betelu, k Jeroboamu, kralju Izraelovemu, in sporočil: Amos je napravil zaroto zoper tebe sredi hiše Izraelove; dežela ne more več prenašati vseh besed njegovih.',
        11: 'Zakaj tako govori Amos: Jeroboam umrje po meču, in Izraela bodo gotovo odpeljali v ujetništvo iz zemlje njegove.',
        12: 'In Amazija veli Amosu: Videc, pojdi, zbeži v deželo Judovo in ondi jej svoj kruh in tam prorokuj;',
        13: 'ali v Betelu nikdar več ne prorokuj, kajti kraljevo svetišče je in dom kraljev je.',
        14: 'In odgovori Amos in reče Amaziju: Nisem bil prorok, tudi nisem bil izmed sinov proroških, ampak črednik sem bil in sem obiral divje smokve.',
        15: 'Vzel pa me je Gospod, ko sem za čredo hodil, in mi je velel Gospod: Pojdi, prorokuj ljudstvu mojemu Izraelu!',
        16: 'In sedaj poslušaj besedo Gospodovo: Ti praviš: Ne prorokuj o Izraelu in ne govóri zoper hišo Izakovo.',
        17: 'Zato pravi tako Gospod: Žena tvoja postane nečistnica v mestu, in sinovi tvoji in hčere tvoje padejo pod mečem, in zemlja tvoja bo razdeljena z mersko vrvico, ti sam pa umreš v ognušeni zemlji, in Izrael bo gotovo odpeljan v ujetništvo iz dežele svoje.',
    },
    8: {
        1: 'To mi je pokazal Gospod Jehova: Glej, koš z zrelim sadjem.',
        2: 'In reče: Kaj vidiš, Amos? Odgovorim: Koš z zrelim sadjem. In mi reče Gospod: Konec je prišel na ljudstvo moje Izraela; ne pojdem več mimo njega, prizanašajoč mu.',
        3: 'In petje v palači se izprevrže v plakanje tisti dan, govori Gospod Jehova; trupel bo množica, vsepovsod jih bodo metali natihoma.',
        4: 'Čujte to vi, ki bi hoteli pogoltniti potrebnega in uničiti ubožce v deželi,',
        5: 'ki govorite: Da bi le že minil mlaj, da bi prodajali žito, in sobota, da odpremo žitnice, da zmanjšamo mero in povišamo ceno in varamo z lažnivo tehtnico!',
        6: 'da kupimo siromaka za denar in potrebnega za par čevljev in da prodamo pleve za žito!',
        7: 'Gospod je prisegel pri ponosu Jakobovem: Gotovo nikdar ne pozabim vseh njih del!',
        8: 'Kako naj bi se za to ne tresla dežela in ne žaloval vsak prebivalec v njej? Res se vsa razlije kakor Nil, požene valove in upade kakor reka v Egiptu.',
        9: 'In zgodi se tisti dan, govori Gospod Jehova, da ukažem solncu zaiti opoldne ter spravim temo nad zemljo ob belem dne.',
        10: 'In izpremenim praznike vaše v žalovanje in vse pesmi vaše v žalostinke in napravim raševnike za vsaka ledja in spravim na vsako glavo plešo, in naredim deželo enako kakor ob žalovanju po edinem sinu in njen konec kakor dan bridkosti.',
        11: 'Glej, pridejo dnevi, govori Gospod Jehova, da pošljem lakoto v deželo, a ne bodo lačni kruha in ne žejni vode, ampak da poslušajo besede Gospodove.',
        12: 'In bodo tavali od morja do morja in od severa k vzhodu, tekali bodo semtertja, da iščejo besede Gospodove, pa je ne bodo našli.',
        13: 'Tisti dan bodo lepe device in zali mladeniči omedlevali od žeje,',
        14: 'kateri prisegajo pri grehu Samarije in govore: Kakor res živi tvoj bog, o Dan! Tudi: Kakor res živi pot v Bersebo! in padejo in ne vstanejo več.',
    },
    9: {
        1: 'Videl sem Gospoda stati nad oltarjem, in je velel: Udari na stebrov glavič, da se tresejo pragi, in razbij jih v kosce na glavo njih vseh; in kar jih še preostane, pomorim z mečem: kdor se spusti v beg, ne ubeži, niti eden iz njih se ne reši.',
        2: 'Ko bi pridrli v kraj mrtvih, tudi odtod jih izvleče roka moja, in ko bi stopili v nebesa, jih odondod privedem doli;',
        3: 'in ko bi se skrili na vrhu Karmela, jih poiščem in vzamem odtod; in ko bi se izpred mojih oči poskrili v globočine morja, tam zapovem kači, da jih piči;',
        4: 'in ko bi šli v sužnost pred svojimi sovražniki, tam zapovem meču, da jih pomori. In obrnem oko svoje proti njim v hudo in ne v dobro.',
        5: 'Kajti Gospod, Jehova nad vojskami, on se dotakne zemlje, in se taja in žalujejo vsi prebivalci na njej in se vsa razlije kakor Nil in zopet upade kakor reka egiptovska;',
        6: 'on je zgradil v nebesih zgornji hram svoj in si utrdil obok nad zemljo; on kliče morske vode ter jih razliva po površju zemlje: Jehova je ime njegovo.',
        7: 'Ali mi niste, o sinovi Izraelovi, kakor otroci Etiopcev? govori Gospod. Nisem li peljal Izraela iz dežele Egiptovske, Filistejcev pa iz Kaftorja in Sircev iz Kira?',
        8: 'Glej, oči Gospoda Jehove so obrnjene zoper to pregrešno kraljestvo, in ga potrebim s površja zemlje; samo da docela ne iztrebim hiše Jakobove, govori Gospod.',
        9: 'Kajti glej, jaz ukažem, in rešetali bodo sinove Izraelove med vsemi narodi, kakor se trese žito na rešetu; a nobeno zrnce ne pade na tla.',
        10: 'Pod mečem umrjo vsi grešniki ljudstva mojega, kateri govore: Ne približa se nam in ne zadene nas nesreča.',
        11: 'Tisti dan vzdignem šator Davidov, ki je razpadel, in zazidam razpoke njegove in postavim razvaline njegove, in zidal ga bom kakor v dneh starodavnih;',
        12: 'da dobodo v last ostanek Edoma in vse narode, nad katerimi se je klicalo moje ime, govori Gospod, ki to napravlja.',
        13: 'Glej, pridejo dnevi, govori Gospod, ko bo stopal orač precej za ženjcem in tlačilec grozdja takoj za sejalcem; in z gorá bo kapljalo sladko vino in vsi griči se raztajajo.',
        14: 'In pripeljem nazaj ujetništvo ljudstva svojega Izraela; in zgradili bodo opustošena mesta in v njih prebivali, in zasajali bodo vinograde in vino iz njih pili, in narejali bodo vrtove in jedli sadje ž njih.',
        15: 'In zasadim jih na njih zemljo, in ne bodo več izruvani iz zemlje svoje, ki sem jo jim dal, pravi Gospod, Bog tvoj.',
    },
}
